counts: Counter[str] = Counter()
pair_support: Counter[tuple[str, str]] = Counter()
for raw_files in commits:
    touched: set[str] = set()
    for raw in raw_files:
        normalized = normalize_py_path(repo_root, fold_rename(renames, raw))
        if normalized is None:
            continue
        if keep_paths is not None and normalized not in keep_paths:
            continue
        touched.add(normalized)
    # Empty (no `.py` / no kept file) and sweeping commits both abstain: the
    # cap is applied AFTER filtering so it counts only files that can rank.
    if not touched or len(touched) > max_commit_files:
        continue
    for f in touched:
        counts[f] += 1
    for a, b in combinations(sorted(touched), 2):
        pair_support[(a, b)] += 1
return CoChangeData(counts=dict(counts), pair_support=dict(pair_support))

